#!/usr/bin/env node
/**
 * Environment Variables Verification - Story 1.1 baseline.
 *
 * Checks only the shell-level env vars this story introduces:
 *   - NEXT_PUBLIC_APP_URL
 *   - NEXTAUTH_URL
 *   - NEXTAUTH_SECRET
 *   - Sentry DSN (optional but warned)
 *
 * Additional keys (DATABASE_URL, STRIPE_*, GEMINI, GROQ, UPSTASH_*, RESEND_*)
 * are added by the stories that introduce those features.
 *
 * Usage: pnpm run deploy:verify
 */

import * as fs from "fs";
import * as path from "path";

interface EnvRequirement {
  name: string;
  required: boolean;
  pattern?: RegExp;
  description: string;
  helpUrl?: string;
}

const ENV_REQUIREMENTS: EnvRequirement[] = [
  {
    name: "NEXT_PUBLIC_APP_URL",
    required: true,
    pattern: /^https?:\/\//,
    description: "Canonical public URL used for SEO metadata base",
  },
  {
    name: "NEXTAUTH_URL",
    required: true,
    pattern: /^https?:\/\//,
    description: "NextAuth origin URL (must be HTTPS in production)",
  },
  {
    name: "NEXTAUTH_SECRET",
    required: true,
    pattern: /^.{32,}$/,
    description: "NextAuth secret (min 32 characters)",
  },
  {
    name: "SENTRY_DSN",
    required: false,
    description: "Server-side Sentry DSN (optional in dev)",
  },
  {
    name: "NEXT_PUBLIC_SENTRY_DSN",
    required: false,
    description: "Client-side Sentry DSN (optional in dev)",
  },
];

const colors = {
  reset: "\x1b[0m",
  red: "\x1b[31m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  blue: "\x1b[34m",
  cyan: "\x1b[36m",
  bold: "\x1b[1m",
};

function log(message: string, color: string = colors.reset): void {
  console.log(`${color}${message}${colors.reset}`);
}

function loadEnvFile(filePath: string): Record<string, string> {
  const env: Record<string, string> = {};

  if (!fs.existsSync(filePath)) return env;

  const content = fs.readFileSync(filePath, "utf-8");
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;

    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (!match) continue;

    const key = match[1].trim();
    let value = match[2].trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function verifyEnvironment(): boolean {
  log("\n==============================================", colors.cyan);
  log("  Fracture Recovery - Environment Verification", colors.cyan);
  log("==============================================\n", colors.cyan);

  const envLocal = loadEnvFile(path.join(process.cwd(), ".env.local"));
  const envProd = loadEnvFile(
    path.join(process.cwd(), ".env.production.local")
  );
  const env = { ...process.env, ...envLocal, ...envProd };

  let passed = 0;
  let failed = 0;
  let warnings = 0;
  const errors: string[] = [];

  for (const req of ENV_REQUIREMENTS) {
    const value = env[req.name];

    if (!value || value.includes("[") || value.includes("replace-with")) {
      if (req.required) {
        log(`  [FAIL] ${req.name}`, colors.red);
        log(`         ${req.description}`, colors.reset);
        if (req.helpUrl) log(`         Get from: ${req.helpUrl}`, colors.blue);
        errors.push(req.name);
        failed++;
      } else {
        log(`  [SKIP] ${req.name} (optional)`, colors.yellow);
        warnings++;
      }
    } else if (req.pattern && !req.pattern.test(value)) {
      log(`  [WARN] ${req.name} - format may be incorrect`, colors.yellow);
      log(`         ${req.description}`, colors.reset);
      warnings++;
    } else {
      log(`  [PASS] ${req.name}`, colors.green);
      passed++;
    }
  }

  log("\n==============================================", colors.cyan);
  log("  Verification Summary", colors.cyan);
  log("==============================================", colors.cyan);
  log(`  Passed:   ${passed}`, colors.green);
  log(`  Warnings: ${warnings}`, colors.yellow);
  log(`  Failed:   ${failed}`, colors.red);

  if (failed > 0) {
    log("\n  Status: NOT READY FOR DEPLOYMENT", colors.red);
    log("\n  Missing required variables:", colors.red);
    errors.forEach((e) => log(`    - ${e}`, colors.red));
    log(
      "\n  Fill in values in .env.local (dev) or .env.production.local (prod).",
      colors.reset
    );
    return false;
  }

  if (warnings > 0) {
    log("\n  Status: READY (with warnings)", colors.yellow);
    return true;
  }

  log("\n  Status: READY FOR DEPLOYMENT", colors.green);
  return true;
}

const isReady = verifyEnvironment();
process.exit(isReady ? 0 : 1);

/**
 * Story 1.1 shell smoke E2E.
 *
 * Purpose: prove the empty marketing shell renders on both mobile and desktop,
 * has the expected global chrome (header / footer / legal links), and resolves
 * all legal placeholder routes.
 *
 * Scope is deliberately minimal. Landing copy and visual regression tests
 * land in Story 1.2 / 1.3 and 7.x respectively.
 */
import { expect, test } from "@playwright/test";

test.describe("marketing shell", () => {
  test("home page renders hero, header, footer", async ({ page }) => {
    await page.goto("/");

    await expect(
      page.getByRole("heading", { level: 1 })
    ).toContainText(/recover/i);

    await expect(page.getByTestId("marketing-header")).toBeVisible();
    await expect(page.getByTestId("marketing-footer")).toBeVisible();
    await expect(page.getByTestId("landing-safety")).toBeVisible();

    await expect(page).toHaveTitle(/Fracture Recovery Companion/i);
  });

  test("header exposes get-started CTA and primary nav", async ({ page }) => {
    await page.goto("/");

    const header = page.getByTestId("marketing-header");
    await expect(header.getByRole("link", { name: /how it works/i })).toBeVisible();
    await expect(header.getByRole("link", { name: /get started/i })).toBeVisible();
  });

  test("footer links resolve all 4 legal placeholder pages", async ({ page }) => {
    const legalPaths = [
      { path: "/legal/privacy", testId: "legal-privacy", title: /Privacy Policy/i },
      { path: "/legal/terms", testId: "legal-terms", title: /Terms of Service/i },
      { path: "/legal/refund", testId: "legal-refund", title: /Refund Policy/i },
      { path: "/legal/disclaimer", testId: "legal-disclaimer", title: /Medical Disclaimer/i },
    ];

    for (const { path, testId, title } of legalPaths) {
      await page.goto(path);
      await expect(page.getByTestId(testId)).toBeVisible();
      await expect(page.getByRole("heading", { level: 1 })).toContainText(title);
      await expect(page.getByTestId("marketing-footer")).toBeVisible();
    }
  });

  test("unknown route renders not-found page", async ({ page }) => {
    const res = await page.goto("/this-route-does-not-exist");
    expect(res?.status()).toBe(404);
    await expect(page.getByRole("heading", { level: 1 })).toContainText(
      /couldn/i
    );
  });
});
